args.query:
SELECT activity__active_date::date AS day, SUM(value_moments) AS habits_completed, SUM(active_sessions) AS sessions FROM (
  SELECT activity__active_date, COUNT(*) FILTER (WHERE activity_type='habit_complete') AS value_moments, COUNT(*) FILTER (WHERE activity_type='session_start') AS active_sessions
  FROM fct_activity
  WHERE activity__active_date BETWEEN '2026-06-29' AND '2026-07-05'
  GROUP BY activity__active_date
) t GROUP BY day ORDER BY day;
